546: function roomFromPos(x,z){
547:   if(x<-4 && z<-2) return 'bedroom';
548:   if(x<-6 && z>=-2 && z<3) return 'bathroom';
549:   if(x>-4 && x<4 && z<-0) return 'living';
550:   if(x>=4 && z<-1) return 'kitchen';
551:   if(x>=4 && z>=-1) return 'study';
552:   if(z>1 && z<3) return 'hallway';
553:   if(z>=3) return 'copy';
554:   return 'hallway';
555: }
