569:   profile.roomTime[S.roomNow]=(profile.roomTime[S.roomNow]||0)+dt; saveProfile();
570:   // trusted room event
571:   if((S.roomTimers[S.roomNow]||0)>18 && now-S.lastEvent>22000){
572:     S.lastEvent=now; S.roomTimers[S.roomNow]=0;
573:     const evts=[
574:       ()=>{ photoMeshes.forEach(p=>{p.material.map=photoStates[1](); p.material.needsUpdate=true;}); toast('A photograph has changed while you weren\'t looking.'); },
575:       ()=>{ playKnock(new THREE.Vector3(player.position.x+2,0,player.position.z),0.5); showSubtitle('— a knock, from inside the walls —'); },
576:       ()=>{ playWhisper(new THREE.Vector3(player.position.x-2,0,player.position.z)); },
577:       ()=>{ if(breathGain) breathGain.gain.value=0.02; setTimeout(()=>{if(breathGain)breathGain.gain.value=0;},5000); showSubtitle('— breathing, nearby, in rhythm with you —'); },
578:       ()=>{ playSilence(1.8); },
579:     ];
580:     evts[Math.floor(Math.random()*evts.length)]();
581:     updateUnease(S.unease+4);
582:   }
583:   // footsteps echo (matching rhythm)
