591:     S.hallwayLong=true; hiddenDoorWall.position.z=3.6; wall(0,7,21,0.3); // crude stretch visual
592:     playCreak(); toast('The hallway is longer than it was. You are certain. You took a photo. The photo shows the same length.'); updateUnease(S.unease+6);
593:   }
