604:   if(S.unease>85 && !S.ended){ tenantGoto(player.position.x,player.position.z); if(Math.hypot(player.position.x-tenant.position.x,player.position.z-tenant.position.z)<1.2){ profile.caught++; saveProfile(); endGame('replacement'); } }
