607: // ============ MOVEMENT & COLLISION ============
608: function collide(pos){
609:   for(const c of colliders){
610:     if(pos.x>c.x1-0.3 && pos.x<c.x2+0.3 && pos.z>c.z1-0.3 && pos.z<c.z2+0.3){
611:       const dx1=pos.x-(c.x1-0.3), dx2=(c.x2+0.3)-pos.x, dz1=pos.z-(c.z1-0.3), dz2=(c.z2+0.3)-pos.z;
612:       const m=Math.min(dx1,dx2,dz1,dz2);
613:       if(m===dx1) pos.x=c.x1-0.3; else if(m===dx2) pos.x=c.x2+0.3; else if(m===dz1) pos.z=c.z1-0.3; else pos.z=c.z2+0.3;
614:     }
615:   }
616:   pos.x=THREE.MathUtils.clamp(pos.x,-10,10); pos.z=THREE.MathUtils.clamp(pos.z,-6.6,6.6);
617: }
618: let stepPhase=0, lastStepTime=0;
619: function updatePlayer(dt){
620:   let mx=0,mz=0;
621:   if(keys['w']||keys['arrowup']) mz-=1; if(keys['s']||keys['arrowdown']) mz+=1; if(keys['a']||keys['arrowleft']) mx-=1; if(keys['d']||keys['arrowright']) mx+=1;
622:   mx+=joyVec.x; mz+=joyVec.y;
623:   const moving=Math.hypot(mx,mz)>0.1;
624:   S.running=keys['shift']&&moving; if(S.running){profile.runTime+=dt; saveProfile();}
625:   let speed=S.running?3.8:(S.sneak?1.0:2.1);
626:   if(S.hiding) speed=0;
627:   if(moving){
628:     const f=new THREE.Vector3(-Math.sin(yaw),0,-Math.cos(yaw));
629:     const r=new THREE.Vector3(Math.cos(yaw),0,-Math.sin(yaw));
630:     const dir=new THREE.Vector3().addScaledVector(f,-mz).addScaledVector(r,mx).normalize();
631:     player.position.addScaledVector(dir,speed*dt);
632:     // head bob + steps
633:     stepPhase+=dt*(S.running?11:7);
634:     if(Date.now()-lastStepTime> (S.running?280:S.sneak?500:380)){ lastStepTime=Date.now(); playStep(S.sneak?0.04:S.running?0.3:0.12); if(S.running) {S.tenantAwareness+=1;} }
635:   }
636:   player.position.y=1.6+Math.sin(stepPhase)*0.03*(moving?1:0);
637:   // leaving hiding
638:   if(S.hiding && (keys['w']||keys['a']||keys['s']||keys['d'])) exitHide();
639:   collide(player.position);
640:   S.roomNow=roomFromPos(player.position.x,player.position.z);
641:   camera.position.copy(player.position);
642:   camera.rotation.set(pitch,yaw,0,'YXZ');
643:   flash.position.copy(player.position); flash.target.position.set(player.position.x-Math.sin(yaw)*4, player.position.y-0.3, player.position.z-Math.cos(yaw)*4);
644:   // tenant follow when aware
645:   if(S.tenantAwareness>15 && !tenant.visible){
646:     if(Math.random()<dt*0.1){ tenant.position.set(player.position.x+(Math.random()-0.5)*6,0,player.position.z+(Math.random()-0.5)*6); collide(tenant.position); }
647:   }
648:   if(S.tenantAwareness>40){ tenant.visible=true; tenant.position.lerp(new THREE.Vector3(player.position.x,0,player.position.z), dt*0.6); tenant.lookAt(player.position.x,0,player.position.z); }
649:   // TV live view from above
650:   if(S.tvOn){
651:     tvCam.position.set(player.position.x,3.2,player.position.z+1); tvCam.lookAt(player.position.x,0,player.position.z);
652:     renderer.setRenderTarget(tvRT); renderer.render(scene,tvCam); renderer.setRenderTarget(null);
653:     // draw label onto canvas for "live" feel
654:     const ctx=tvCanvas.getContext('2d'); ctx.fillStyle='rgba(255,0,0,0.9)'; ctx.font='bold 18px monospace'; ctx.fillText('● LIVE — CAM 4 (CEILING)',10,24); tvTex.needsUpdate=true;
655:   }
656: }
657: function updateInteract(){
658:   raycaster.setFromCamera({x:0,y:0},camera); raycaster.far=3.2;
659:   const objs=[...scene.children].filter(o=>o.userData&&o.userData.interact);
660:   const hit=raycaster.intersectObjects(objs,true)[0];
661:   const prompt=document.getElementById('prompt');
662:   if(hit){ let o=hit.object; while(o && !(o.userData&&o.userData.interact)) o=o.parent; currentInteract=o; prompt.textContent=o?.userData?.label||''; prompt.style.display='block'; }
663:   else { currentInteract=null; prompt.style.display='none'; }
664: }
