# CRITICAL BUG: makeDoor colliders are wrong for north-south doors at x=-4 (bedroom) & others.
# For ry=0 doors (bedroom at x=-4 z=-3.5, living at x=-1 z=1), door plane should be along Z axis, i.e. collider narrow in X, long in Z. Current code starts with wide-X and only swaps if sin(ry). Fix directly.
cat > /tmp/opencode/patch_doors.py << 'PYEOF'
import pathlib
p = pathlib.Path('game.js')
t = p.read_text()
old = """  const col={x1:x-width/2-0.1,x2:x+width/2+0.1,z1:z-0.2,z2:z+0.2,temp:true};
  if(Math.abs(Math.sin(ry))>0.5){ col.x1=x-0.2;col.x2=x+0.2;col.z1=z-width/2;col.z2=z+width/2; }"""
new = """  // door group is rotated ry; door leaf spans local X. world collider must match facing.
  const isNS = Math.abs(Math.cos(ry))>0.5; // door plane faces along Z (ry=0 or PI) -> narrow X, long Z
  let col;
  if(isNS){ col={x1:x-0.2,x2:x+0.2,z1:z-width/2-0.1,z2:z+width/2+0.1,temp:true}; }
  else { col={x1:x-width/2-0.1,x2:x+width/2+0.1,z1:z-0.2,z2:z+0.2,temp:true}; }"""
assert old in t
t = t.replace(old, new)
# bathDoor ry=PI/2 -> isNS false -> wide-X collider correct. bedroomDoor ry=0 -> narrow-X correct. livingDoor same. kitchenDoor/studyDoor ry=0 -> narrow-X correct.
# Fix roomFromPos order (bathroom check before living/kitchen to avoid overlap):
old2 = """function roomFromPos(x,z){
  if(x<-4 && z<-2) return 'bedroom';
  if(x<-6 && z>=-2 && z<3) return 'bathroom';
  if(x>-4 && x<4 && z<-0) return 'living';
  if(x>=4 && z<-1) return 'kitchen';
  if(x>=4 && z>=-1) return 'study';
  if(z>1 && z<3) return 'hallway';
  if(z>=3) return 'copy';
  return 'hallway';
}"""
new2 = """function roomFromPos(x,z){
  if(z>=3) return 'copy';
  if(x<-6 && z>=-1.5 && z<3) return 'bathroom';
  if(x<-4 && z<-1.5) return 'bedroom';
  if(x>4 && z<1) return 'kitchen';
  if(x>4 && z>=1) return 'study';
  if(x>-4 && x<=4 && z<1) return 'living';
  return 'hallway';
}"""
assert old2 in t
t = t.replace(old2, new2)
p.write_text(t)
print('ok')
